use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::{fs,path::Path};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/absolute-norm176");let old=fs::read_to_string(r.join("compile-initial/field.rs")).unwrap();let new=fs::read_to_string(r.join("field.rs")).unwrap();assert_eq!(old.matches("Self::splat").count(),1);assert_eq!(new,old.replace("Self::splat","splat"));fs::copy(r.join("field.rs"),r.join("source/crates/zopro-bn254/src/absolute_norm.rs")).unwrap();fs::rename(r.join("native"),r.join("native-initial")).unwrap();let mut pins:Value=serde_json::from_slice(&fs::read(r.join("build-pins.json")).unwrap()).unwrap();for(p,h)in pins.as_object_mut().unwrap(){*h=json!(format!("{:x}",Sha256::digest(fs::read(p).unwrap())));}for f in["repair-compile.rs","compile-initial/field.rs","compile-initial/bootstrap.rs","compile-initial/build-pins.json"]{let p=r.join(f);pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));}fs::write(r.join("build-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();println!("Fixed only private associated helper reference to same free splat; failed compile retained, no tests ran in first attempt");}
